import React from 'react';
import { Discrepancy } from '../App';

interface Props {
  discrepancies: Discrepancy[];
}

const DiscrepancyDashboard: React.FC<Props> = ({ discrepancies }) => {
  // Helper to group by type
  const byType = (type: string) =>
    discrepancies.filter(d => d.type === type);

  const price = byType('Unit Price');
  const formulation = byType('Formulation');
  const strength = byType('Strength');
  const payer = byType('Payer');

  return (
    <div>
      {/* Unit Price Table */}
      {price.length > 0 && (
        <section>
          <h2>Unit Price Discrepancy Analysis</h2>
          <table>
            <thead>
              <tr>
                <th>Drug Name</th>
                <th>Recorded Price</th>
                <th>Reference Price</th>
                <th>Overcharge</th>
                <th>% Discrepancy</th>
              </tr>
            </thead>
            <tbody>
              {price.map((d, i) => (
                <tr key={i}>
                  <td>{d.drugName}</td>
                  <td>${d.invPrice}</td>
                  <td>${d.refPrice}</td>
                  <td>${((d.invPrice ?? 0) - (d.refPrice ?? 0)).toFixed(2)}</td>
                  <td>{d.percentOver}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      )}

      {/* Formulation Table */}
      {formulation.length > 0 && (
        <section>
          <h2>Formulation Discrepancy Analysis</h2>
          <table>
            <thead>
              <tr>
                <th>Drug Name</th>
                <th>Recorded Formulation</th>
                <th>Reference Formulation</th>
              </tr>
            </thead>
            <tbody>
              {formulation.map((d, i) => (
                <tr key={i}>
                  <td>{d.drugName}</td>
                  <td>{d.invFormulation}</td>
                  <td>{d.refFormulation}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      )}

      {/* Strength Table */}
      {strength.length > 0 && (
        <section>
          <h2>Strength Discrepancy Analysis</h2>
          <table>
            <thead>
              <tr>
                <th>Drug Name</th>
                <th>Recorded Strength</th>
                <th>Reference Strength</th>
              </tr>
            </thead>
            <tbody>
              {strength.map((d, i) => (
                <tr key={i}>
                  <td>{d.drugName}</td>
                  <td>{d.invStrength}</td>
                  <td>{d.refStrength}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      )}

      {/* Payer Table */}
      {payer.length > 0 && (
        <section>
          <h2>Payer Discrepancy Analysis</h2>
          <table>
            <thead>
              <tr>
                <th>Drug Name</th>
                <th>Recorded Payer</th>
                <th>Expected Payer</th>
              </tr>
            </thead>
            <tbody>
              {payer.map((d, i) => (
                <tr key={i}>
                  <td>{d.drugName}</td>
                  <td>{d.invPayer}</td>
                  <td>{d.refPayer}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      )}

      {/* No Discrepancies */}
      {discrepancies.length === 0 && (
        <div style={{ margin: 20, color: 'green' }}><b>No discrepancies detected.</b></div>
      )}
    </div>
  );
};

export default DiscrepancyDashboard;
